// ============================================
// MineBench: Choo-Choo Train — Grandfathered Steam Locomotive
// Full 3D build: locomotive + tender + environment
// ============================================

var CX=128, CZ=128;

// ---------- helpers ----------
function cyl(xc,yc,zc,r,type){
  for(var x=xc-r;x<=xc+r;x++){
    for(var y=yc-r;y<=yc+r;y++){
      for(var z=zc-r;z<=zc+r;z++){
        if(x<0||x>255||y<0||y>255||z<0||z>255) continue;
        if(Math.sqrt((x-xc)*(x-xc)+(y-yc)*(y-yc)+(z-zc)*(z-zc))<r) block(x,y,z,type);
      }
    }
  }
}
function cylx(xc,yc,zc,r,h,type){
  for(var x=xc-h;x<=xc+h;x++){
    for(var y=yc-r;y<=yc+r;y++){
      for(var z=zc-r;z<=zc+r;z++){
        if(x<0||x>255||y<0||y>255||z<0||z>255) continue;
        if(Math.sqrt((x-xc)*(x-xc)+(y-yc)*(y-yc)+(z-zc)*(z-zc))<r) block(x,y,z,type);
      }
    }
  }
}
function cylz(xc,yc,zc,r,h,type){
  for(var z=zc-h;z<=zc+h;z++){
    for(var x=xc-r;x<=xc+r;x++){
      for(var y=yc-r;y<=yc+r;y++){
        if(x<0||x>255||y<0||y>255||z<0||z>255) continue;
        if(Math.sqrt((x-xc)*(x-xc)+(y-yc)*(y-yc)+(z-zc)*(z-zc))<r) block(x,y,z,type);
      }
    }
  }
}
function cone(xc,yc,zc,r1,h,r2,type){
  for(var y=0;y<h;y++){
    var t=y/h;
    var r=r1+(r2-r1)*t;
    if(r<0.5) r=0.5;
    cyl(xc,yc+y,zc,r,type);
  }
}
function rng(a,b){return a+Math.floor(Math.random()*(b-a+1));}

