  cyl(tx-3,ty,tz-3,1,14,'iron_block');
  cyl(tx+3,ty,tz-3,1,14,'iron_block');
  cyl(tx-3,ty,tz+3,1,14,'iron_block');
  cyl(tx+3,ty,tz+3,1,14,'iron_block');
  // tank
