  block(tx,ty+15,tz,'bricks');
  block(tx+1,ty+15,tz,'bricks');
  block(tx-1,ty+15,tz,'bricks');
  block(tx,ty+15,tz+1,'bricks');
  block(tx,ty+15,tz-1,'bricks');
  // ladder
  for(var y=ty;y<=ty+14;y+=2){
    block(tx+2,y,tz,'oak_log');
    block(tx+2,y+1,tz,'oak_log');
  }
}
function signal(tx,ty,tz){
